# McGee graph via LCF notation [-12, 7, -7]^8
n = 24
edges = set()

# Cycle edges
for i in range(n):
    u, v = i, (i+1) % n
    if u > v:
        u, v = v, u
    edges.add((u, v))

# Additional edges from LCF
for i in range(n):
    if i % 3 == 0:
        j = (i - 12) % n
    elif i % 3 == 1:
        j = (i + 7) % n
    else:
        j = (i - 7) % n
    u, v = i, j
    if u > v:
        u, v = v, u
    edges.add((u, v))

edges = sorted(edges)
print("Number of edges:", len(edges))
print("Edges:", edges)

# Build adjacency
from collections import defaultdict
adj = defaultdict(set)
for u,v in edges:
    adj[u].add(v)
    adj[v].add(u)

# Check degrees
print("Degrees:", [len(adj[i]) for i in range(n)])

# Compute girth
def compute_girth(adj, n):
    from collections import deque
    girth = float('inf')
    for start in range(n):
        dist = [-1]*n
        parent = [-1]*n
        q = deque([start])
        dist[start] = 0
        while q:
            u = q.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                elif parent[u] != v and parent[v] != u:
                    # found a cycle
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len > 0:
                        girth = min(girth, cycle_len)
    return girth if girth != float('inf') else -1

print("Girth:", compute_girth(adj, n))

# Check 3-colorability
def is_3_colorable(adj, n):
    colors = [-1]*n
    def dfs(u):
        for v in adj[u]:
            if colors[v] == -1:
                for c in range(3):
                    ok = True
                    for w in adj[v]:
                        if colors[w] == c:
                            ok = False
                            break
                    if ok:
                        colors[v] = c
                        if dfs(v):
                            return True
                        colors[v] = -1
                return False
            elif colors[v] == colors[u]:
                return False
        return True
    for start in range(n):
        if colors[start] == -1:
            colors[start] = 0
            if not dfs(start):
                return False, []
    return True, colors

ok, cols = is_3_colorable(adj, n)
print("3-colorable:", ok)
if ok:
    print("Colors:", cols)

